#define SPEED 0.45
#define RINGS 9.0
const float BLOOM = 1.6;

vec3 ramp(float t)
{
    return mix(vec3(0.08, 0.02, 0.25), vec3(1.0, 0.55, 0.15), smoothstep(0.0, 1.0, t));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    float r = length(p);
    float a = atan(p.y, p.x);
    float depth = 0.4 / max(r, 0.02) + iTime * SPEED;
    float rings = 0.5 + 0.5 * sin(depth * RINGS);
    float spokes = 0.5 + 0.5 * cos(a * 6.0 + iTime * 0.3);
    vec3 col = ramp(rings * spokes) * BLOOM * smoothstep(0.0, 0.4, r);
    fragColor = vec4(col, 1.0);
}
